def compute(vars):
    high = vars["v1"]
    low = vars["v2"]
    if high == 0:
        return None
    change_ratio = (low - high) / high
    value = change_ratio * 100
    return {
        "value": value,
        "trace": {
            "old_price": high,
            "new_price": low,
            "change_ratio": change_ratio,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
